#####################################  Install alternative to corosync library to use in pace maker.
# Run me on each node of the cluster!

####### Install pace maker to test the library
[[ ! -z "`cat /etc/os-release | grep NAME | grep Ubuntu`" ]] && IS_UBUNTU="Y" || IS_UBUNTU="N";
if false; then
	if [[ $IS_UBUNTU == "Y" ]]; then	# For Debian/Ubuntu
		sudo apt install pacemaker pcs resource-agents pacemaker-dev;
		sudo apt install crmsh;
	else
		sudo yum install pacemaker-devel;
		sudo rpm -q --queryformat '%{BUILDFLAGS}\n' pacemaker;
	fi
	sudo passwd hacluster;	# Daniel created password 12345
fi
pacemakerd --version;
pacemakerd -F; # | grep custom

####### Install library
echo "Building the library";
make all;
LIB_DIR=/usr/local/lib/;
LIB_NAME="libclusterstack";
sudo rm -f ${LIB_DIR}${LIB_NAME}.so;
cmd="cp ${LIB_NAME}.so ${LIB_DIR}"; echo ${cmd}; eval "sudo ${cmd}";
sudo ls -l "${LIB_DIR}${LIB_NAME}.so";
sudo ldconfig;

if false; then		# Create pace-maker General configuration
	sudo mkdir -p /etc/pacemaker;
	nvmeibc_conf="/etc/pacemaker/pacemaker.conf";
	nvmeibc_conf_marker='# Toma-based corosync';
	sudo rm -f ${nvmeibc_conf};
	sudo tee ${nvmeibc_conf} << EOF
# Toma-based corosync
cluster_stack = "custom"
custom_stack_lib = "${LIB_DIR}${LIB_NAME}.so"
##################
EOF
	sudo ls -l ${nvmeibc_conf};
fi

# Create systemd override for Pacemaker. Can do the below manually via 'sudo systemctl edit pacemaker'
sudo mkdir -p /etc/systemd/system/pacemaker.service.d/
sudo tee /etc/systemd/system/pacemaker.service.d/override.conf << EOF
[Service]
#Environment="PCMK_cluster_type=custom"
Environment="PCMK_stack_file=/usr/local/lib/libclusterstack.so"
EOF

# Update Pacemaker system configuration
if [[ $IS_UBUNTU == "Y" ]]; then	# For Debian/Ubuntu
	PACE_MAKER_SYS_CONF="/etc/default/pacemaker";
else								# For RHEL/CentOS
	PACE_MAKER_SYS_CONF="/etc/sysconfig/pacemaker";
fi
sudo tee -a ${PACE_MAKER_SYS_CONF} << EOF
#PCMK_cluster_type=custom
PCMK_stack_file=/usr/local/lib/libclusterstack.so
PCMK_debug=yes
EOF

# Create log directory
sudo mkdir -p /var/log/cluster
#sudo chown hacluster:haclient /var/log/cluster

# Stop existing corosync, Start pacemaker with new stack
echo "Start using ${LIB_NAME}.so";
if true; then
	# Reload systemd configuration
	sudo systemctl daemon-reload;
	sudo systemctl stop pacemaker;

	# Stop corosync if it's running
	sudo systemctl stop corosync;
	sudo systemctl disable corosync;

	sudo systemctl start pacemaker; # Start Pacemaker
	# sudo PCMK_debug=1 /usr/sbin/pacemakerd -f # Run with debug
	sudo systemctl enable pacemaker; # Enable Pacemaker to start on boot
fi

if true; then		# Check if Pacemaker is using our custom stack
	sudo systemctl status pacemaker; sudo pcs status;
	sudo crm status;
	sudo journalctl -u pacemaker -u corosync;
	#tail -f /var/log/cluster/cluster.log
	sudo less -N /var/log/pacemaker/pacemaker.log;
fi

# SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0

#####################################  Compile plugin into corosync library to be an arbiter.
# Run executable on each node of the cluster, or insert the code into Toma so toma is the executable!

####### Install corosync
	# 1. sources (for compiling arbiter
	# 2. rpm for running coro_sync in case that pace maker with coro_sync does not exist
[[ ! -z "`cat /etc/os-release | grep NAME | grep Ubuntu`" ]] && IS_UBUNTU="Y" || IS_UBUNTU="N";

cur_dir=${PWD};
CORO_SRC="/home/${USER}/projects/corosync";
if [ ! -d ${CORO_SRC} ]; then
	if [[ $IS_UBUNTU == "Y" ]]; then	# For Debian/Ubuntu
		sudo apt install libknet1 libknet-dev libnss3-dev libnet1-dev groff;  # Libraries to compile arbiter
		# sudo apt install libnspr4-dev
		# Todo: rpm for corosync only. Installing pace maker below brings corosync but this is an overkill
		# sudo apt install pacemaker pcs resource-agents pacemaker-dev crmsh;
	else								# Centos
		# Todo:
		sudo yum install pacemaker-devel;
		sudo rpm -q --queryformat '%{BUILDFLAGS}\n' pacemaker;
	fi

	cd ~/projects/;
	git clone https://github.com/corosync/corosync.git
	cd corosync;
	./autogen.sh;
	./configure;
	make;

	if false; then	# Install qdevice plugin into corosync lib - not needed, we work directly with corosync api
		git clone https://github.com/corosync/corosync-qdevice.git
	fi
	cd ${cur_dir};
else
	echo "Coro_sync repo already exists";
fi

####### Check corosync version
if true; then
	/usr/sbin/corosync -v;
	sudo find /usr -name "corosync";
fi

####### Run test environment of corosync, do in different terminal
if false; then
	# Stop corosync: optional
	COR_LOG_FILE="/var/log/corosync/corosync.log";
	ps -ef | grep coro;
	sudo systemctl stop corosync;
	sudo rm -f ${COR_LOG_FILE}

	# Prepare unitest test cluster
	sudo cp ./corosync_cluster.conf /etc/corosync/corosync.conf;

	# Run corosync in foreground debug mode
	clear; sudo /usr/sbin/corosync -f;
	# Monitor: sudo journalctl -u corosync; less ${COR_LOG_FILE};
fi

####### Compile and run the arbiter
if true; then
	echo "Compile the arbiter";
	EXE_NAME="arbiter";

	# clean all
	cmd="rm -f ${EXE_NAME}.[od] ${EXE_NAME}; rm -rf ./.libs";
	echo -e "\n_______\n${cmd}"; eval ${cmd};

	FLAGS="-g -O2  -fPIC -DPIC  -fPIE -O3 -ggdb3 -Wall -Wshadow -Wmissing-prototypes -Wmissing-declarations -Wstrict-prototypes -Wpointer-arith -Wwrite-strings -Wcast-align -Wbad-function-cast -Wmissing-format-attribute -Wformat=2 -Wformat-security -Wformat-nonliteral -Wno-long-long -Wno-strict-aliasing";
	cmd="gcc -I${CORO_SRC}/include/corosync -I${CORO_SRC}/include ${FLAGS} -pthread -MT ${EXE_NAME}.o -MD -MP -c -o ${EXE_NAME}.o ${EXE_NAME}.c";
	echo -e "\n_______\n${cmd}"; eval ${cmd};
	cmd="${CORO_SRC}/libtool --silent --tag=CC --mode=link gcc ${FLAGS} -pthread -fPIC -DPIC -pie -Wl,-z,relro -Wl,-z,now  -Wl,--as-needed -o ${EXE_NAME} ${EXE_NAME}.o ${CORO_SRC}/lib/libvotequorum.la -lqb -lrt -lpthread";
	echo -e "\n_______\n${cmd}"; eval ${cmd};

	# Cleanup intermediate build results
	rm ${EXE_NAME};
	cp .libs/${EXE_NAME} ${EXE_NAME};
	rm -rf ./.libs;

	echo -e "\n_______ run_exe\n";
	sudo ./${EXE_NAME};
fi

